const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/schedule/summary',
  qs: {
    after: 'SOME_STRING_VALUE',
    before: 'SOME_STRING_VALUE',
