  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/schedule/summary?after=SOME_STRING_VALUE&before=SOME_STRING_VALUE&limit_per_day=SOME_INTEGER_VALUE&project_ids=SOME_ARRAY_VALUE&project_stage_ids=SOME_ARRAY_VALUE&project_type_ids=SOME_ARRAY_VALUE&project_department_ids=SOME_ARRAY_VALUE&project_office_ids=SOME_ARRAY_VALUE&project_region_ids=SOME_ARRAY_VALUE&project_owner_type_ids=SOME_ARRAY_VALUE&program_ids=SOME_ARRAY_VALUE&resource_ids=SOME_ARRAY_VALUE&query=SOME_STRING_VALUE&summary=SOME_BOOLEAN_VALUE&milestone=SOME_BOOLEAN_VALUE&project_role_ids=SOME_ARRAY_VALUE&assignee_ids=SOME_ARRAY_VALUE&milestone_ids=SOME_ARRAY_VALUE&sort_key=SOME_STRING_VALUE&sort_dir=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
